-- Ajoute Serre-Ponçon comme 3e centre de couverture POI (comme Chambéry et Rouen) — un
-- contributeur y a ajouté ses propres parcours (baie St Michel, lac de Serre-Ponçon),
-- une zone jusque-là juste hors de la couverture Chambéry.
-- `on conflict (id) do nothing` : les lieux déjà connus (zone Chambéry, qui recouvre
-- partiellement) sont ignorés, seuls les nouveaux sont ajoutés.
